// carved bevel: bright offset toward light, dark offset away, base on top
function carveGlyph(g, aFade){
  const s=g.s; const off=Math.max(1.2,s*0.05);
  const base = (style==='painted')? g.paint : (C.neg? [C.sH,C.sS,C.sB+4] : [g.paint[0],g.paint[1],g.paint[2]]);
  const dark = C.neg? [C.sH,C.sS,6] : [C.shH, C.sS*0.8, C.sB*C.shB];
  const lite = [C.lt[0], C.lt[1]*0.5, C.lt[2]];
